/*
 * Native bodies of each PSX image's functions (generated by tools/pclink.py).
 *
 * Game code takes and stores function addresses as PSX addresses. When an
 * image is in memory, the runtime writes a `jmp` to the native body at each of
 * its functions' PSX addresses, so calls through those addresses (function
 * pointers in game data, calls into another overlay) reach the right code.
 */
#ifndef PC_THUNKS_H
#define PC_THUNKS_H

#include <stdint.h>

typedef struct PcThunk {
    uint32_t psx_addr;
    void (*native)(void);
} PcThunk;

typedef struct PcImageThunks {
    const char* image; /* "main", "gameplay", "title", or an overlay name */
    const PcThunk* thunks; /* sorted by PSX address */
    unsigned count;
    /* Where the image loads and how to recognize it there: FNV-1a hashes of
     * its first bytes and of its constant part (rodata and code, the first
     * code_size bytes), with the bytes thunks cover read as zero (see
     * tools/pclink.py, image_fingerprint). */
    uint32_t load;
    uint32_t size;
    uint32_t code_size;
    uint64_t prefix_hash;
    uint64_t full_hash;
} PcImageThunks;

/* Recognizes images the game has loaded into PSX RAM since the last call
 * and installs their thunks (replacing those of the image they overwrote).
 * Cheap when nothing changed. Returns the number of images installed. */
int pc_scan_images(void);

/* Nonzero to log image installs (set by the host). */
extern int pc_trace_images;

extern const PcImageThunks pc_image_thunks[];
extern const unsigned pc_image_thunk_count;

/* What booting the main executable needs beyond the image read from disc. */
typedef struct PcMainImage {
    int (*entry)(void);  /* native body of the game's main() */
    uint32_t bss_start;  /* PSX range crt0 zeroes before main() */
    uint32_t bss_end;
} PcMainImage;

extern const PcMainImage pc_main_image;

/* Writes a jmp to each native body at its PSX address for `image`. Returns
 * the number installed, or -1 if the image is unknown. */
int pc_install_thunks(const char* image);

/* Library routines of the main image (generated by tools/pclink.py): the
 * runtime's implementation, and the stub that interprets the original MIPS
 * code. They differ when the runtime implements the routine natively. */
typedef struct PcRuntimeFn {
    uint32_t psx_addr;
    void (*impl)(void);
    void (*stub)(void);
    const char* name;
} PcRuntimeFn;

extern const PcRuntimeFn pc_runtime_fns[];
extern const unsigned pc_runtime_fn_count;

/* Installs thunks to the native implementations of library routines, so
 * calls through their PSX addresses (from interpreted code or function
 * pointers) reach them. Returns the number installed. */
int pc_install_runtime_thunks(void);

/* Nonzero when a thunk to native code is installed at `addr`. */
int pc_thunk_at(uint32_t addr);

/* Forgets the thunks recorded in [start, start + size) (the image there was
 * replaced). */
void pc_clear_thunks(uint32_t start, uint32_t size);

#endif /* PC_THUNKS_H */
